SELECT DATE(usage_start_time,'Europe/Istanbul') AS day, service.description AS service, sku.id AS sku_id, sku.description AS sku, COALESCE(resource.global_name,resource.name,'') AS resource, TO_JSON_STRING(labels) AS labels, currency, usage.unit AS usage_unit, usage.pricing_unit AS pricing_unit, SUM(usage.amount) AS usage_amount, SUM(usage.amount_in_pricing_units) AS pricing_amount, SUM(cost) AS gross_try, SUM(IFNULL((SELECT SUM(c.amount) FROM UNNEST(credits) c),0)) AS credits_try, SUM(cost+IFNULL((SELECT SUM(c.amount) FROM UNNEST(credits) c),0)) AS net_try, SUM(cost_at_list) AS list_try, MIN(currency_conversion_rate) AS fx_min, MAX(currency_conversion_rate) AS fx_max, MIN(usage_start_time) AS earliest_usage, MAX(usage_end_time) AS latest_usage, MAX(export_time) AS latest_export, COUNT(*) AS row_count
FROM `project-27082a40-6083-4952-9db.billing_export.gcp_billing_export_resource_v1_017786_B62E9C_E21182`
WHERE (_PARTITIONTIME >= TIMESTAMP('2026-10-31') OR _PARTITIONTIME IS NULL) AND usage_start_time >= TIMESTAMP('2026-11-01 00:00:00+03') AND usage_start_time < CURRENT_TIMESTAMP() AND project.id='project-27082a40-6083-4952-9db'
GROUP BY day,service,sku_id,sku,resource,labels,currency,usage_unit,pricing_unit ORDER BY day,net_try DESC